const { useState } = React;

function App() {
  const [page, setPage] = useState("dashboard");
  const [dateRange, setDateRange] = useState("Last 30 days");
  const [exportMessage, setExportMessage] = useState("");

  function handleExport() {
    setExportMessage("Export started");
    setTimeout(() => setExportMessage(""), 3000);
  }

  if (page === "newProject") {
    return (
      <div style={styles.app}>
        <header style={styles.navbar}>
          <div style={styles.logo}>Insight</div>
          <nav style={styles.navLinks} aria-label="Main navigation">
            <button style={styles.navButton} onClick={() => setPage("dashboard")}>Dashboard</button>
            <button style={styles.navButton} onClick={() => setPage("projects")}>Projects</button>
            <button style={{...styles.navButton, textDecoration: "underline"}} onClick={() => setPage("team")}>Team</button>
          </nav>
          <button style={styles.newProjectButton} onClick={() => setPage("newProject")}>New project</button>
        </header>
        <main style={styles.main}>
          <h1>New project</h1>
          <p>This is the New project page.</p>
          <button onClick={() => setPage("dashboard")}>Back to Dashboard</button>
        </main>
      </div>
    );
  }

  return (
    <div style={styles.app}>
      <header style={styles.navbar}>
        <div style={styles.logo}>Insight</div>
        <nav style={styles.navLinks} aria-label="Main navigation">
          <button style={{...styles.navButton, textDecoration: "underline"}} onClick={() => setPage("dashboard")}>Dashboard</button>
          <button style={styles.navButton} onClick={() => setPage("projects")}>Projects</button>
          <button style={styles.navButton} onClick={() => setPage("team")}>Team</button>
        </nav>
        <button style={styles.newProjectButton} onClick={() => setPage("newProject")}>New project</button>
      </header>
      <main style={styles.main}>
        <form
          onSubmit={e => {
            e.preventDefault();
            handleExport();
          }}
          style={styles.form}
          aria-label="Date range and export form"
        >
          <label htmlFor="dateRange" style={styles.label}>
            <select
              id="dateRange"
              value={dateRange}
              onChange={e => setDateRange(e.target.value)}
              style={styles.select}
            >
              <option>Last 7 days</option>
              <option>Last 30 days</option>
              <option>This year</option>
            </select>
          </label>
          <button type="submit" style={styles.exportButton}>Export</button>
        </form>
        {exportMessage && (
          <p role="alert" style={styles.exportMessage}>{exportMessage}</p>
        )}

        <section aria-label="Traffic chart" style={styles.chartContainer}>
          <svg
            viewBox="0 0 100 40"
            style={styles.chart}
            aria-hidden="true"
            focusable="false"
          >
            <polyline
              fill="none"
              stroke="#007bff"
              strokeWidth="2"
              points="0,30 20,35 40,10 60,15 80,12 100,30"
            />
          </svg>
        </section>

        <section style={styles.cardsContainer}>
          <article style={styles.card} aria-label="Tasks done">
            <h3>Tasks done</h3>
            <p>................................</p>
            <p>................................</p>
          </article>
          <article style={styles.card} aria-label="Open issues">
            <h3>Open issues</h3>
            <p>................................</p>
            <p>................................</p>
          </article>
        </section>
      </main>
    </div>
  );
}

